function CERTIFIED_LOWER_BOUND(F, S, g, P):
    acc <- 0
    for f in F:
        if P(f): acc <- acc + 1
    randomProb <- acc / |F|
    pacc <- 0
    for s in S:
        if P(g(s)): pacc <- pacc + 1
    pseudoProb <- pacc / |S|
    advantage <- |randomProb - pseudoProb|
    delta <- randomProb            # largeness parameter
    eps   <- pseudoProb            # realized leak
    return (delta, eps, advantage >= delta - eps)

function BARRIER_HOLDS(F, S, g, P, C, delta):
    # class-to-family bridge
    range_in_class <- for all s in S: C(g(s))
    useful_vs_C    <- for all f in F with P(f): not C(f)
    if range_in_class and useful_vs_C:
        useful <- TRUE                 # bridge conclusion
    else:
        useful <- for all s in S: not P(g(s))
    large <- randomProb(P) >= delta
    if large and useful:
        return advantage(P,g) >= delta # g NOT delta-secure
    return TRUE                         # no obstruction shown
